const point=p=>'PCH.'+String(p).padStart(3,'0');
function fields(n){
 if(n.kind==='comment')return [];
 if(n.kind==='referenceSend')return [{key:'input',label:'Сигнал',type:'pch'}];
 if(n.kind==='referenceReceive')return [];
 if(n.kind==='source')return [];
 if(n.kind==='constant')return [{key:'value',label:'Значення',type:'number',param:'5.'+(120+n.resource),min:-32000,max:32000}];
 if(n.kind==='sink')return [{key:'input',label:'Сигнал',type:'pch',param:n.param}];
 const f=fn(n.code),out=[];
 for(const s of f.signature)out.push({key:s.toUpperCase(),label:s.toUpperCase(),type:s===s.toLowerCase()?'pch':'number',param:'6.'+((n.slot-1)*4+2+'ABC'.indexOf(s.toUpperCase()))});
 const p=(key,label,param,type='pch',min,max)=>out.push({key,label,param:'5.'+param,type,min,max});
 if(n.code===40){p('EN','EN',40);p('LEN','LEN · стани',42,'number',2,8);for(let i=0;i<8;i++)p('D'+i,'Час '+(i+1)+' · 0,1 с',43+i);['NEXT','PREV','CLR','SET','SETVAL'].forEach((s,i)=>p(s,s,51+i));}
 if(n.code===41||n.code===42){let b=n.code===41?60:80;p('EN','EN',b);p('DV','Вихід при EN=0',b+2,'number',-32000,32000);p('SEL','SELECT · 0…7',b+3);for(let i=0;i<8;i++)p('I'+i,'IN '+i,b+4+i);}
 if(n.code===43){p('X','X',101);for(let i=0;i<5;i++){p('X'+i,'X'+(i+1),102+i*2,'number',-32000,32000);p('Y'+i,'Y'+(i+1),103+i*2,'number',-32000,32000);}}
 return out;
}
function outputs(n){if(n.kind==='comment')return [];if(n.kind==='referenceSend')return [];if(n.kind==='referenceReceive')return Number.isInteger(n.pch)&&n.pch>=0?[n.pch]:[];if(n.kind==='source')return [n.pch];if(n.kind==='constant')return [320+n.resource];if(n.kind==='sink'||[47,49].includes(n.code))return [];if(n.code===40)return [312,...Array.from({length:8},(_,i)=>304+i)];if(n.code===41)return [313];if(n.code===42)return [314];if(n.code===43)return [315];return [255+n.slot];}
if(typeof module!=='undefined')module.exports={FUNCTIONS,fn,PCH,fields,outputs,point};
